type Data={contracts:Stored<Contract>[];requirements:Stored<Requirement>[];fields:DataField[];packs:Stored<AssurancePack>[];extracts:ExtractedDocument[];lines:Stored<FmtLine>[];budgets:Stored<Budget>[];mappings:Stored<AccountMapping>[];actuals:Actual[];pendingActuals:Actual[];library:Reference[];xero:{configured:boolean;connected:boolean;updated:string;mode:string;scopes:string}|null};
